import{_ as t,o as i,c as r,ae as n}from"./chunks/framework.BvHJbMD4.js";const c=JSON.parse('{"title":"Geheime Medien & Dokumente","description":"","frontmatter":{},"headers":[],"relativePath":"medien.md","filePath":"medien.md"}'),a={name:"medien.md"};function o(s,e,d,u,l,m){return i(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="geheime-medien-dokumente" tabindex="-1">Geheime Medien &amp; Dokumente <a class="header-anchor" href="#geheime-medien-dokumente" aria-label="Permalink to &quot;Geheime Medien &amp; Dokumente&quot;">​</a></h1><p>Hier sammeln wir das (fiktive) Beweismaterial, das unsere Mockumentary stützt. Warnung: Einige dieser Dokumente gelten in bestimmten Kreisen als &quot;nicht existent&quot;.</p><h2 id="📄-leaked-die-sacher-serviette-rekonstruktion" tabindex="-1">📄 Leaked: Die &quot;Sacher-Serviette&quot; (Rekonstruktion) <a class="header-anchor" href="#📄-leaked-die-sacher-serviette-rekonstruktion" aria-label="Permalink to &quot;📄 Leaked: Die &quot;Sacher-Serviette&quot; (Rekonstruktion)&quot;">​</a></h2><p>Dieses Dokument bildet das Herzstück von Teil 4. Es handelt sich um eine Original-Serviette aus dem Hotel Sacher, auf der in Heidis Handschrift (und mit Lippenstift-Abdruck am Rand) die erste strategische Skizze der &quot;Pointillismus-Spenden&quot; festgehalten wurde.</p><div class="info custom-block"><p class="custom-block-title">ANALYSE DES DOKUMENTS</p><ul><li><strong>Notiz 1:</strong> &quot;Gernot anrufen. Er braucht wieder Porto.&quot;</li><li><strong>Notiz 2:</strong> &quot;49k x 20 = ? (Rechner im Tresor prüfen)&quot;</li><li><strong>Skizze:</strong> Ein kleiner Berg aus Punkten, der wie ein Diamant geformt ist.</li></ul></div><h2 id="🎬-storyboard-skizze-die-marktbereinigung" tabindex="-1">🎬 Storyboard-Skizze: Die Marktbereinigung <a class="header-anchor" href="#🎬-storyboard-skizze-die-marktbereinigung" aria-label="Permalink to &quot;🎬 Storyboard-Skizze: Die Marktbereinigung&quot;">​</a></h2><p>Eine erste Skizze für die Schlüsselszene in Teil 2.</p><ul><li><strong>Szene 14:</strong> Horten (Diehl) sitzt im Schatten. Das Licht der Zigarre ist der einzige Fixpunkt.</li><li><strong>Kameraperspektive:</strong> Low-Angle, um seine Machtposition gegenüber den schwindenden Kaufhauserben zu betonen.</li></ul><h2 id="📜-archiv-fund-der-kaufvertrag" tabindex="-1">📜 Archiv-Fund: Der &quot;Kaufvertrag&quot; <a class="header-anchor" href="#📜-archiv-fund-der-kaufvertrag" aria-label="Permalink to &quot;📜 Archiv-Fund: Der &quot;Kaufvertrag&quot;&quot;">​</a></h2><p>Ein Dokumententwurf für die Übernahme der Alsberg-Häuser aus dem Jahr 1933. Der Preis wurde mehrfach mit Rotstift korrigiert, bis er fast bei Null lag. Ein handschriftlicher Vermerk am Rand lautet: <em>&quot;Marktüblich. Effizient. Erledigt.&quot;</em></p>',10)])])}const k=t(a,[["render",o]]);export{c as __pageData,k as default};
